    x = observation.get("position_x", 0)
    y = observation.get("position_y", 0)
    # Simple, robust policy: move toward the nearest objective if present, otherwise stay or wander slightly.
    # Look for common resource/territory indicators
    targets = []
    if isinstance(observation.get("resources"), (list, tuple)):
