        # In pursuit evasion, avoid but keep some bias away from nearest enemy
        pass

    # Determine a simple goal delta based on known fields
    goal_dx = 0
    goal_dy = 0

    # If there are explicit relative goals, try to move toward their average position
    rels = []
    if isinstance(observation.get("resource_positions"), (list, tuple)):
        rels.extend(observation.get("resource_positions", []))
    if isinstance(observation.get("territory_positions"), (list, tuple)):
        rels.extend(observation.get("territory_positions", []))

    if rels:
        # Each entry is expected to be a [rx, ry] relative or absolute; normalize to relative from self
        for r in rels:
            if isinstance(r, (list, tuple)) and len(r) >= 2:
                rx, ry = r[0], r[1]
                # Prefer moving toward positive alignment
                goal_dx += (rx - x)
                goal_dy += (ry - y)

        # Average the influence
        n = len(rels)
        if n > 0:
            goal_dx //= n
            goal_dy //= n

    # Bound dx, dy to -1..1
    if goal_dx > 1:
        goal_dx = 1
    if goal_dx < -1:
        goal_dx = -1
    if goal_dy > 1:
        goal_dy = 1
    if goal_dy < -1:
        goal_dy = -1

    # If no goal computed, do a small random-like but deterministic pattern using position to create a slight patrol
    if goal_dx == 0 and goal_dy == 0:
        # deterministic "hover" pattern based on position
        if (x + y) % 3 == 0:
            goal_dx, goal_dy = 1, 0
        elif (x + y) % 3 == 1:
            goal_dx, goal_dy = 0, 1
        else:
            goal_dx, goal_dy = -1, 0

    # Ensure final move in allowed set
    if goal_dx not in (-1, 0, 1):
        goal_dx = 0
    if goal_dy not in (-1, 0, 1):
        goal_dy = 0

    return [goal_dx, goal_dy]

